graphql.query:
query ProductPage($id: ID!) {
  productById(id: $id) {
    id
    sku
    title
    description
    category
    price {
      amount
      currency
    }
    availableQuantity
    averageRating
    reviews(first: 3) {
      totalCount
      pageInfo {
        hasNextPage
      }
      nodes {
        rating
        body
        createdAt
        author {
          displayName
        }
      }
    }
  }
}

query BySku($sku: String!) {
  productBySku(sku: $sku) {
    id
    sku
    title
    price {
      amount
      currency
    }
  }
}

query Refetch($id: ID!) {
  node(id: $id) {
    __typename
    id
    ... on Product {
      sku
      title
    }
  }
}

{
  __schema {
    queryType {
      name
    }
    types {
      name
    }
  }
  __type(name: "Node") {
    kind
    possibleTypes {
      name
    }
  }
}

{
  products {
    title
    reviews(first: 2) {
      nodes {
        rating
        author {
          displayName
        }
      }
    }
  }
}

{
  browseProducts(first: 3) {
    totalCount
    nodes {
      id
      title
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

query NextPage($after: String) {
  browseProducts(first: 3, after: $after) {
    nodes {
      title
    }
  }
}

{
  browseProducts(
    first: 2
    where: { category: { eq: LIGHTING } }
    order: [{ title: DESC }]
  ) {
    nodes {
      title
      category
      averageRating
    }
  }
}

query ReviewPage($sku: String!) {
  productBySku(sku: $sku) {
    sku
    reviews(first: 2) {
      totalCount
      pageInfo {
        hasNextPage
        endCursor
      }
      nodes {
        id
        rating
        author {
          id
          displayName
        }
      }
    }
  }
}

query NextReviewPage($sku: String!, $after: String) {
  productBySku(sku: $sku) {
    reviews(first: 2, after: $after) {
      nodes {
        id
        rating
        author {
          displayName
        }
      }
    }
  }
}

query Unreviewed($sku: String!) {
  productBySku(sku: $sku) {
    id
    sku
    title
    reviews(first: 5) {
      totalCount
      pageInfo {
        hasNextPage
      }
      nodes {
        id
        rating
      }
    }
  }
}

{
  products {
    sku
  }
  browseProducts(first: 25) {
    totalCount
    nodes {
      sku
    }
  }
}

{
  current: __type(name: "Query") {
    fields {
      name
    }
  }
  all: __type(name: "Query") {
    fields(includeDeprecated: true) {
      name
      isDeprecated
      deprecationReason
    }
  }
}

mutation SubmitReview($input: SubmitReviewInput!) {
  submitReview(input: $input) {
    review {
      id
      rating
    }
    errors {
      __typename
      ... on Error {
        message
        code
      }
      ... on RatingOutOfRangeError {
        min
        max
      }
    }
  }
}

mutation SubmitReview($input: SubmitReviewInput!) {
  submitReview(input: $input) {
    review {
      id
      rating
      body
      createdAt
      author {
        id
        displayName
      }
    }
    errors {
      __typename
      ... on Error {
        message
        code
      }
      ... on RatingOutOfRangeError {
        min
        max
      }
    }
  }
}

